      const dotted = model.replace(/-(\d+)-(\d+)$/, '-$1.$2');
      const zgHit = zg[model] ?? zg[dotted];
      if (opts.provider !== 'anthropic' && zgHit) return tag(zgHit);
      return STATIC_PRICES[model] ?? (zgHit ? tag(zgHit) : { prompt: 0, completion: 0, source: 'unknown' });
    },
  };
}

